1	const express = require('express');
2	const router = express.Router();
3	const axios = require('axios');
4	const { User, EvaluationParticipant } = require('../models');
5	const { syncEligibleEvaluationParticipants, listEvaluationParticipants } = require('../services/evaluationParticipants');
6	const { verifyToken, requireRole } = require('../middlewares/auth');
7	const { shouldWriteLog, createSecurityLog, createSecurityLogRecord } = require('../services/securityAudit');
8	
9	// FACE_AI_URL is the BASE url of the InsightFace service; paths are appended.
10	const FACE_AI_URL = () => process.env.FACE_AI_URL || 'http://127.0.0.1:8501';
11	
12	// Base64 data-URL frames are ~1.33x the JPEG size; 8 MB of text comfortably
13	// covers the 420px-wide compressed frames the scanners send, and rejects abuse.
14	const MAX_IMAGE_CHARS = 8 * 1024 * 1024;
15	
16	// --- Access control -----------------------------------------------------------
17	// Gate Scanner / V-Patrol run under an FM session. A trusted edge device (e.g. a
18	// future Pi node posting frames itself) may authenticate with EDGE_SERVICE_TOKEN
19	// in an x-edge-token header instead of a user JWT.
20	const allowFMOrEdgeService = (req, res, next) => {
21	  const edgeToken = req.headers['x-edge-token'];
22	  if (edgeToken && process.env.EDGE_SERVICE_TOKEN && edgeToken === process.env.EDGE_SERVICE_TOKEN) {
23	    return next();
24	  }
25	  return verifyToken(req, res, () => requireRole('FM')(req, res, next));
26	};
27	
28	
29	const validateFrame = (image) => {
30	  if (typeof image !== 'string' || !image.startsWith('data:image/')) {
31	    return { status: 400, error: 'A base64 data-URL image is required.' };
32	  }
33	  if (image.length > MAX_IMAGE_CHARS) {
34	    return { status: 413, error: 'Image payload too large.' };
35	  }
36	  return null;
37	};
38	
39	const forwardRecognitionFrame = async (image) => {
40	  const startedAt = Date.now();
41	  const aiResponse = await axios.post(`${FACE_AI_URL()}/user/recognize`, { image }, {
42	    timeout: 15000,
43	    headers: { 'X-AI-Service-Key': process.env.AI_SERVICE_KEY || '' }
44	  });
45	  return { aiResult: aiResponse.data || {}, totalRequestMs: Date.now() - startedAt };
46	};
47	
48	const livenessStatus = (ratio) => {
49	  if (typeof ratio !== 'number') return 'unavailable';
50	  return ratio < 0.35 || ratio > 0.65 ? 'movement-detected' : 'front-facing';
51	};
52	
53	// GET is intentionally read-only; POST performs the explicit FM-controlled backfill.
54	router.get('/evaluation-participants', verifyToken, requireRole('FM'), async (_req, res) => {
55	  try { return res.status(200).json({ participants: await listEvaluationParticipants() }); }
56	  catch (error) { console.error('Evaluation participant list error:', error); return res.status(500).json({ error: 'Could not load evaluation participants.' }); }
57	});
58	router.post('/evaluation-participants/sync', verifyToken, requireRole('FM'), async (_req, res) => {
59	  try { const assigned = await syncEligibleEvaluationParticipants(); return res.status(200).json({ synced: assigned.length, participants: await listEvaluationParticipants() }); }
60	  catch (error) { console.error('Evaluation participant sync error:', error); return res.status(500).json({ error: 'Could not sync evaluation participants.' }); }
61	});
62	// POST /api/facial-recognition/evaluate
63	// FM-only side-effect-free model evaluation. It forwards one temporary frame to
64	// FastAPI and returns safe telemetry only. It never creates Attendance,
65	// SecurityLogs, User updates, or enrolment changes, and never stores the frame.
66	router.post('/evaluate', verifyToken, requireRole('FM'), async (req, res) => {
67	  const validation = validateFrame(req.body?.image);
68	  if (validation) return res.status(validation.status).json({ error: validation.error });
69	
70	  try {
71	    const { aiResult, totalRequestMs } = await forwardRecognitionFrame(req.body.image);
72	    const {
73	      matchedUserId = null,
74	      confidence = 0,
75	      box = null,
76	      liveness_ratio = null,
77	      faceDetected = false,
78	      inference_ms = null
79	    } = aiResult;
80	
81	    const outcome = faceDetected === false || (!box && matchedUserId == null)
82	      ? 'NO_FACE'
83	      : matchedUserId == null ? 'UNKNOWN' : 'MATCHED';
84	
85	    let subject = null;
86	    if (matchedUserId != null) {
87	      const user = await User.findByPk(matchedUserId, {
88	        attributes: ['id', 'name', 'role', 'isActive', 'isEnrolled']
89	      });
90	      if (user) {
91	        const participant = await EvaluationParticipant.findOne({ where: { userId: user.id }, attributes: ['evaluationLabel'] });
92	        subject = {
93	          id: user.id,
94	          name: user.name,
95	          role: user.role,
96	          isActive: Boolean(user.isActive),
97	          isEnrolled: Boolean(user.isEnrolled),
98	          evaluationLabel: participant?.evaluationLabel || null
99	        };
100	      }
101	    }
102	    const policyDecision = outcome === 'NO_FACE' ? 'NONE'
103	      : subject?.isActive && subject?.isEnrolled ? 'GRANTED' : 'DENIED';
104	
105	    // Still-image policy evaluation excludes live anti-spoofing/head-turn verification.
106	    return res.status(200).json({
107	      matchedUserId: matchedUserId == null ? null : matchedUserId,
108	      outcome,
109	      confidence,
110	      box,
111	      subject,
112	      predictedEvaluationLabel: outcome === 'NO_FACE' ? null : outcome === 'UNKNOWN' ? 'Unknown' : subject?.evaluationLabel || null,
113	      noFace: outcome === 'NO_FACE',
114	      latencyMs: totalRequestMs,
115	      policyDecision,
116	      liveness: {
117	        ratio: liveness_ratio,
118	        status: livenessStatus(liveness_ratio)
119	      },
120	      timings: {
121	        inferenceMs: inference_ms,
122	        totalRequestMs
123	      }
124	    });
125	  } catch (err) {
126	    const isConnError = !err.response &&
127	      ['ECONNREFUSED', 'ECONNABORTED', 'ETIMEDOUT', 'ENOTFOUND'].includes(err.code);
128	    if (isConnError) {
129	      return res.status(503).json({ error: 'Facial recognition service is offline. Please try again shortly.' });
130	    }
131	    if (err.response) {
132	      const status = err.response.status === 400 ? 400 : 502;
133	      return res.status(status).json({ error: 'Facial recognition service returned an error.' });
134	    }
135	    console.error('Evaluation forwarding error:', err.message);
136	    return res.status(502).json({ error: 'Facial recognition service returned an error.' });
137	  }
138	});
139	// POST /api/facial-recognition/access-event
140	// V-Patrol monitoring: records a server-owned SAFE access audit event for a
141	// verified (recognised + liveness-passed) active user WITHOUT touching
142	// attendance - V-Patrol must never toggle clock-in/out; that is the Gate
143	// Scanner's job via /api/attendance/scan. Deduplicated server-side.
144	router.post('/access-event', allowFMOrEdgeService, async (req, res) => {
145	  try {
146	    const { userId, cameraLocation } = req.body;
147	    if (userId == null || !Number.isInteger(Number(userId))) {
148	      return res.status(400).json({ error: 'Missing required parameter: userId' });
149	    }
150	    const location = typeof cameraLocation === 'string' && cameraLocation.trim()
151	      ? cameraLocation.trim().slice(0, 100)
152	      : 'Biometric Gantry';
153	
154	    const user = await User.findByPk(userId, {
155	      attributes: ['id', 'name', 'role', 'isActive', 'isEnrolled']
156	    });
157	    if (!user || !user.isEnrolled) {
158	      return res.status(404).json({ error: 'User not recognized in system registry.' });
159	    }
160	    if (!user.isActive) {
161	      return res.status(403).json({ error: 'Account suspended. Access event not recorded as granted.' });
162	    }
163	
164	    // Same dedup namespace as the attendance scan, so a person passing both the
165	    // gantry and the turnstile within the cooldown yields ONE safe log, not two.
166	    let logged = false;
167	    if (shouldWriteLog(`granted:${user.id}:${location}`)) {
168	      logged = await createSecurityLog({
169	        type: 'Gantry Access',
170	        desc: `Identity & liveness verified: ${user.name} (${user.role}) at ${location}.`,
171	        severity: 'safe',
172	        // Stable token — the client renders the matching MUI icon.
173	        icon: 'UNLOCK',
174	        personnelName: user.name,
175	        matchedUserId: user.id,
176	        cameraLocation: location
177	      });
178	    }
179	
180	    // Safe fields only - never the biometric template.
181	    return res.status(200).json({
182	      status: 'SUCCESS',
183	      logged,
184	      worker: user.name,
185	      role: user.role
186	    });
187	  } catch (err) {
188	    console.error('Access-event error:', err);
189	    return res.status(500).json({ error: 'Could not record access event.' });
190	  }
191	});
192	
193	// POST /api/facial-recognition/denied-event
194	// V-Patrol's final DENIED outcomes (identity mismatch, liveness timeout,
195	// persistent multiple faces). The client may only name WHICH allowed reason
196	// occurred — the server owns type/description/severity/icon/review status and
197	// resolves the candidate's name/role from PostgreSQL. Never creates
198	// Attendance, never modifies a User, never stores an image or embedding.
199	const DENIED_EVENT_ALLOWED_FIELDS = ['reason', 'candidateUserId', 'cameraLocation', 'confidence'];
200	const DENIED_EVENT_RULES = {
201	  FINAL_IDENTITY_MISMATCH: {
202	    type: 'Identity Confirmation Failure',
203	    severity: 'critical',
204	    icon: 'DENIED',
205	    dedupKey: (identity, location) => `denied:final-confirmation:${identity}:${location}`,
206	    describe: (location) => `Initial identity could not be confirmed during the final same-person check at ${location}.`
207	  },
208	  LIVENESS_TIMEOUT: {
209	    type: 'Liveness Verification Failed',
210	    severity: 'critical',
211	    icon: 'DENIED',
212	    dedupKey: (identity, location) => `denied:liveness:${identity}:${location}`,
213	    describe: (location) => `Motion-liveness head-turn verification timed out at ${location}.`
214	  },
215	  MULTIPLE_FACES: {
216	    type: 'Multiple Faces Detected',
217	    severity: 'critical',
218	    icon: 'ALERT',
219	    dedupKey: (_identity, location) => `denied:multiple-faces:${location}`,
220	    describe: (location) => `Multiple faces were detected during an access-verification attempt at ${location}.`
221	  }
222	};
223	
224	router.post('/denied-event', allowFMOrEdgeService, async (req, res) => {
225	  try {
226	    const body = req.body || {};
227	    const unknownFields = Object.keys(body).filter((k) => !DENIED_EVENT_ALLOWED_FIELDS.includes(k));
228	    if (unknownFields.length) {
229	      return res.status(400).json({ error: `Unexpected field(s): ${unknownFields.join(', ')}.` });
230	    }
231	
232	    const rule = DENIED_EVENT_RULES[body.reason];
233	    if (typeof body.reason !== 'string' || !rule) {
234	      return res.status(400).json({ error: 'reason must be one of: FINAL_IDENTITY_MISMATCH, LIVENESS_TIMEOUT, MULTIPLE_FACES.' });
235	    }
236	
237	    if (body.candidateUserId != null && !Number.isInteger(Number(body.candidateUserId))) {
238	      return res.status(400).json({ error: 'candidateUserId must be a numeric user id or null.' });
239	    }
240	    const candidateUserId = body.candidateUserId == null ? null : Number(body.candidateUserId);
