1	const express = require('express');
2	const router = express.Router();
3	const { Op } = require('sequelize');
4	const { verifyToken } = require('../middlewares/auth');
5	const {
6	  User,
7	  Attendance,
8	  Camera,
9	  DetectionAlert,
10	  Booking,
11	  IncidentLog,
12	  SupportTicket,
13	  SecurityLog
14	} = require('../models');
15	const {
16	  getSingaporeWindow,
17	  deriveDailySummaries,
18	  summarizeForDate,
19	  buildAttendanceWhere
20	} = require('../services/attendanceSummary');
21	
22	const ACTIVE_ALERT_STATUSES = ['Active', 'Acknowledged', 'Investigating', 'Escalated', 'Dispatched'];
23	const HIGH_SEVERITIES = ['High', 'Critical'];
24	const OPEN_INCIDENT_STATUSES = ['Active', 'Pending Review', 'Escalated', 'Open'];
25	const OPEN_TICKET_STATUSES = ['Pending', 'In Progress'];
26	const ACTIVE_BOOKING_STATUSES = ['Confirmed', 'Arrived'];
27	
28	const safeCount = async (model, options = {}) => {
29	  if (!model || typeof model.count !== 'function') return null;
30	  return model.count(options);
31	};
32	
33	const todayWindow = () => getSingaporeWindow({ filter: 'today' });
34	
35	const attendanceForUsers = async (userWhere) => {
36	  const window = todayWindow();
37	  const records = await Attendance.findAll({
38	    where: buildAttendanceWhere(window),
39	    include: [{ model: User, attributes: ['id', 'name', 'role', 'managerId'], ...(userWhere ? { where: userWhere } : {}) }],
40	    order: [['timestamp', 'ASC']]
41	  });
42	  const summaries = deriveDailySummaries(records);
43	  return { window, summaries, today: summarizeForDate(summaries, window.todayKey) };
44	};
45	
46	const safeBookingFields = ['id', 'booking_ref', 'tenantId', 'tenant_name', 'transport_company', 'license_plate', 'loading_bay', 'slot_start', 'slot_end', 'status'];
47	
48	router.get('/summary', verifyToken, async (req, res) => {
49	  try {
50	    const { id: userId, role } = req.user;
51	    const window = todayWindow();
52	
53	    if (role === 'FM') {
54	      const attendance = await attendanceForUsers();
55	      const [cameraTotal, camerasOnline, camerasOffline, urgentDetectionAlerts, todayBookings, activeVehicles, openIncidents, openSupportTickets] = await Promise.all([
56	        safeCount(Camera),
57	        safeCount(Camera, { where: { status: 'Online' } }),
58	        safeCount(Camera, { where: { status: 'Offline' } }),
59	        safeCount(DetectionAlert, { where: { severity: { [Op.in]: HIGH_SEVERITIES }, status: { [Op.in]: ACTIVE_ALERT_STATUSES } } }),
60	        safeCount(Booking, { where: { slot_start: { [Op.gte]: window.start, [Op.lt]: window.end } } }),
61	        safeCount(Booking, { where: { status: { [Op.in]: ACTIVE_BOOKING_STATUSES } } }),
62	        safeCount(IncidentLog, { where: { [Op.or]: [{ resolutionStatus: { [Op.in]: OPEN_INCIDENT_STATUSES } }, { status: { [Op.in]: OPEN_INCIDENT_STATUSES } }] } }),
63	        safeCount(SupportTicket, { where: { status: { [Op.in]: OPEN_TICKET_STATUSES } } })
64	      ]);
65	
66	      const recentHighPriorityAlerts = DetectionAlert?.findAll ? await DetectionAlert.findAll({
67	        where: { severity: { [Op.in]: HIGH_SEVERITIES }, status: { [Op.in]: ACTIVE_ALERT_STATUSES } },
68	        attributes: ['id', 'zone_name', 'camera_location', 'status', 'object_class', 'alert_type', 'severity', 'source', 'occurred_at', 'createdAt'],
69	        order: [['createdAt', 'DESC']],
70	        limit: 5
71	      }) : [];
72	
73	      return res.json({
74	        role: 'FM',
75	        summary: {
76	          cameras: { total: cameraTotal, online: camerasOnline, offline: camerasOffline },
77	          attendance: {
78	            peopleCurrentlyOnSite: attendance.today.onSite,
79	            checkedInToday: attendance.today.checkedIn,
80	            checkedOutToday: attendance.today.checkedOut
81	          },
82	          urgentDetectionAlerts,
83	          todaysLoadingBayBookings: todayBookings,
84	          activeOrArrivedVehicles: activeVehicles,
85	          openIncidents,
86	          openSupportTickets
87	        },
88	        recentHighPriorityAlerts: recentHighPriorityAlerts.map((alert) => (typeof alert.toJSON === 'function' ? alert.toJSON() : alert))
89	      });
90	    }
91	
92	    if (role === 'Tenant') {
93	      const attendance = await attendanceForUsers({ role: 'Staff', managerId: userId });
94	      const [staffTotal, todayBookings, openSupportCases] = await Promise.all([
95	        safeCount(User, { where: { role: 'Staff', managerId: userId } }),
96	        safeCount(Booking, { where: { tenantId: userId, slot_start: { [Op.gte]: window.start, [Op.lt]: window.end } } }),
97	        safeCount(SupportTicket, { where: { userId, status: { [Op.in]: OPEN_TICKET_STATUSES } } })
98	      ]);
99	
100	      const nextBooking = Booking?.findOne ? await Booking.findOne({
101	        where: { tenantId: userId, status: { [Op.notIn]: ['Completed', 'Cancelled'] }, slot_start: { [Op.gte]: new Date() } },
102	        attributes: safeBookingFields,
103	        order: [['slot_start', 'ASC']]
104	      }) : null;
105	
106	      const recentActivity = Booking?.findAll ? await Booking.findAll({
107	        where: { tenantId: userId },
108	        attributes: safeBookingFields,
109	        order: [['updatedAt', 'DESC']],
110	        limit: 5
111	      }) : [];
112	
113	      return res.json({
114	        role: 'Tenant',
115	        summary: {
116	          staffTotal,
117	          staffCurrentlyOnSite: attendance.today.onSite,
118	          staffLateToday: attendance.today.late,
119	          todaysOwnBookings: todayBookings,
120	          ownOpenSupportCases: openSupportCases
121	        },
122	        nextBooking: nextBooking ? (typeof nextBooking.toJSON === 'function' ? nextBooking.toJSON() : nextBooking) : null,
123	        recentActivity: recentActivity.map((item) => (typeof item.toJSON === 'function' ? item.toJSON() : item))
124	      });
125	    }
126	
127	    const attendance = await attendanceForUsers({ id: userId });
128	    const ownToday = attendance.today.summaries[0] || null;
129	    const account = User?.findByPk ? await User.findByPk(userId, { attributes: ['id', 'isEnrolled'] }) : null;
130	
131	    return res.json({
132	      role: 'Staff',
133	      summary: {
134	        currentClockStatus: ownToday?.currentStatus || 'OUT',
135	        todayFirstClockIn: ownToday?.firstCheckIn || null,
136	        todayLatestClockOut: ownToday?.latestCheckOut || null,
137	        punctuality: ownToday?.punctuality || 'NO_IN',
138	        faceIdEnrolled: Boolean(account?.isEnrolled)
139	      },
140	      nextRelevantBooking: null,
141	      unavailable: {
142	        nextRelevantBooking: 'No staff-to-booking ownership link exists in the current schema.'
143	      },
144	      quickLinks: [
145	        { label: 'My Attendance', to: '/attendance' },
146	        { label: 'Logistics', to: '/logistics' },
147	        { label: 'Settings', to: '/settings' }
148	      ]
149	    });
150	  } catch (err) {
151	    console.error('Dashboard summary error:', err);
152	    return res.status(500).json({ error: 'Failed to load dashboard summary.' });
153	  }
154	});
155	
156	module.exports = router;

