142	.logout-btn {
143	  display: block;
144	  width: 100%;
145	  padding: 10px;
146	  background: rgba(239, 68, 68, 0.1);
147	  color: #ef4444;
148	  border: 1px solid rgba(239, 68, 68, 0.2);
149	  border-radius: 8px;
150	  text-align: center;
151	  font-weight: 600;
152	  cursor: pointer;
153	  transition: background 0.2s, color 0.2s;
154	}
155	
156	.logout-btn:hover {
157	  background: #ef4444;
158	  color: white;
159	}
160	
161	/* =========================================
162	   MANUAL ADD-USER MODAL FORM (scoped; used by User Management + My Staff)
163	   Reuses the shared .modal-overlay / .modal-content; only adds dark form fields.
164	   ========================================= */
165	.add-user-form {
166	  display: flex;
167	  flex-direction: column;
168	  gap: 14px;
169	  text-align: left;
170	  margin-top: 8px;
171	}
172	.add-user-form label {
173	  display: block;
174	  color: #94a3b8;
175	  font-size: 0.85rem;
176	  margin-bottom: 6px;
177	}
178	.add-user-form input {
179	  width: 100%;
180	  box-sizing: border-box;
181	  background: #0b0f1a;
182	  border: 1px solid #334155;
183	  color: #f8fafc;
184	  padding: 10px 12px;
185	  border-radius: 8px;
186	  font-size: 0.9rem;
187	  outline: none;
188	  transition: border-color 0.2s, box-shadow 0.2s;
189	}
190	.add-user-form input:focus { border-color: #3b82f6; box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15); }
191	/* Keep autofilled values dark instead of the browser's white/yellow fill. */
192	.add-user-form input:-webkit-autofill,
193	.add-user-form input:-webkit-autofill:hover,
194	.add-user-form input:-webkit-autofill:focus {
195	  -webkit-text-fill-color: #f8fafc;
196	  -webkit-box-shadow: 0 0 0 1000px #0b0f1a inset;
197	  caret-color: #f8fafc;
198	}
199	.add-user-btn {
200	  background: #3b82f6;
201	  color: #fff;
202	  border: none;
203	  border-radius: 8px;
204	  padding: 10px 18px;
205	  font-weight: 600;
206	  font-size: 0.9rem;
207	  cursor: pointer;
208	  transition: background 0.2s, box-shadow 0.2s;
209	}
210	.add-user-btn:hover { background: #2563eb; }
211	.add-user-btn:focus-visible { outline: none; box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.4); }
212	.add-user-error { color: #f87171; font-size: 0.9rem; margin-bottom: 12px; }
213	
214	/* =========================================
215	   3. MAIN CONTENT DASHBOARD
216	   ========================================= */
217	.dashboard-main {
218	  flex: 1;
219	  padding: 30px;
220	  overflow-y: auto;
221	  overflow-x: hidden;
222	}
223	
224	.dashboard-header {
225	  display: flex;
226	  justify-content: space-between;
227	  align-items: center; 
228	  margin-bottom: 30px;
229	}
230	
231	.header-titles h1 { 
232	  font-size: 1.8rem; 
233	  margin: 0; 
234	}
235	
236	.header-titles p { 
237	  color: #707a91; 
238	  font-size: 0.85rem; 
239	  margin: 5px 0 0 0; 
240	}
241	
242	.header-time { 
243	  text-align: right; 
244	}
245	
246	.time-text { 
247	  font-weight: 600; 
248	  margin: 0 0 5px 0; 
249	  color: #e2e8f0; 
250	  font-size: 0.95rem;
251	}
252	
253	.timezone-text { 
254	  font-size: 0.8rem; 
255	  color: #707a91; 
256	  margin: 0; 
257	}
258	
259	/* --- GRID SYSTEM (3-Column Top) --- */
260	.top-summary-row {
261	  display: grid;
262	  grid-template-columns: repeat(3, 1fr);
263	  gap: 20px;
264	  margin-bottom: 30px;
265	}
266	
267	.summary-card {
268	  background: #1e2539;
269	  padding: 20px;
270	  border-radius: 12px;
271	  display: flex;
272	  align-items: center;
273	  gap: 15px;
274	  border: 1px solid #2d364f;
275	}
276	
277	.icon-wrapper {
278	  width: 45px;
279	  height: 45px;
280	  border-radius: 10px;
281	  display: flex;
282	  align-items: center;
283	  justify-content: center;
284	  font-size: 1.2rem;
285	}
286	
287	.blue-icon { background: rgba(59, 130, 246, 0.15); color: #60a5fa; }
288	.purple-icon { background: rgba(168, 85, 247, 0.15); color: #c084fc; }
289	.red-icon { background: rgba(239, 68, 68, 0.15); color: #f87171; }
290	
291	.summary-info h2 { margin: 0; font-size: 1.6rem; color: #f8fafc; }
292	.summary-info p { margin: 0; color: #707a91; font-size: 0.8rem; }
293	
294	.green-icon { background: rgba(16, 185, 129, 0.15); color: #34d399; }
295	
296	.dashboard-link-card {
297	  color: inherit;
298	  text-decoration: none;
299	  transition: transform 0.18s ease, border-color 0.18s ease;
300	}
301	
302	.dashboard-link-card:hover {
303	  transform: translateY(-2px);
304	  border-color: #3b82f6;
305	}
306	
307	.dashboard-summary-grid {
308	  grid-template-columns: repeat(3, minmax(180px, 1fr));
309	}
310	
311	.dashboard-detail-grid {
312	  display: grid;
313	  grid-template-columns: repeat(2, minmax(240px, 1fr));
314	  gap: 20px;
315	  margin-bottom: 30px;
316	}
317	
318	.dashboard-loading,
319	.dashboard-error {
320	  background: #1e2539;
321	  border: 1px solid #2d364f;
322	  border-radius: 8px;
323	  padding: 24px;
324	  color: #94a3b8;
325	}
326	
327	.dashboard-error {
328	  color: #fecdd3;
329	  border-color: rgba(244, 63, 94, 0.35);
330	  background: rgba(244, 63, 94, 0.1);
331	  display: flex;
332	  align-items: center;
333	  justify-content: space-between;
334	  gap: 16px;
335	  flex-wrap: wrap;
336	}
337	
338	.dashboard-retry-btn {
339	  background: #334155;
340	  color: #e2e8f0;
341	  border: 1px solid #475569;
342	  border-radius: 8px;
343	  padding: 8px 18px;
344	  font-weight: 700;
345	  cursor: pointer;
346	}
347	
348	.dashboard-retry-btn:hover {
349	  background: #475569;
350	}
351	
352	.icon-wrapper svg {
353	  font-size: 1.35rem;
354	}
355	
356	.summary-helper {
357	  display: block;
358	  margin-top: 2px;
359	  color: #94a3b8;
360	  font-size: 0.72rem;
361	}
362	
363	.chart-card h3 svg,
364	.dashboard-quick-links a svg {
365	  vertical-align: -3px;
366	  margin-right: 4px;
367	}
368	
369	.dashboard-muted {
370	  color: #94a3b8;
371	}
372	
373	.dashboard-quick-links {
374	  display: flex;
375	  flex-wrap: wrap;
376	  gap: 10px;
377	}
378	
379	.dashboard-quick-links a {
380	  color: #60a5fa;
381	  border: 1px solid rgba(96, 165, 250, 0.35);
382	  border-radius: 8px;
383	  padding: 8px 12px;
384	  text-decoration: none;
385	  font-size: 0.85rem;
386	  font-weight: 700;
387	}
388	/* --- RECENT ACTIVITY (4-Column Middle) --- */
389	.activity-cards-grid {
390	  display: grid;
391	  grid-template-columns: repeat(4, 1fr);
392	  gap: 20px;
393	  margin-bottom: 30px;
394	}
395	
396	.activity-card {
397	  background: #1e2539;
398	  padding: 25px;
399	  border-radius: 12px;
400	  text-align: center;
401	  border: 1px solid #2d364f;
402	}
403	
404	.act-icon { font-size: 1.5rem; }
405	.activity-card h2 { font-size: 2rem; margin: 10px 0; }
406	.activity-card p { font-size: 0.8rem; color: #707a91; margin: 0; }
407	
408	.dashboard-alert-section {
409	  margin-bottom: 30px;
410	}
411	
412	.dashboard-section-heading {
413	  display: flex;
414	  align-items: flex-start;
415	  justify-content: space-between;
416	  gap: 16px;
417	  margin-bottom: 14px;
418	}
419	
420	.dashboard-section-heading h3 {
421	  margin: 0;
422	  color: #e2e8f0;
423	  font-size: 1rem;
424	}
425	
426	.dashboard-section-heading p {
427	  margin: 4px 0 0;
428	  color: #707a91;
429	  font-size: 0.82rem;
430	}
431	
432	.dashboard-section-heading a {
433	  color: #60a5fa;
434	  border: 1px solid rgba(96, 165, 250, 0.35);
435	  border-radius: 8px;
436	  padding: 8px 12px;
437	  text-decoration: none;
438	  font-size: 0.82rem;
439	  font-weight: 700;
440	}
441	
442	.dashboard-alert-grid {
443	  display: grid;
444	  grid-template-columns: repeat(3, minmax(180px, 1fr));
445	  gap: 16px;
446	}
447	
448	.dashboard-alert-card,
449	.dashboard-alert-empty {
450	  min-height: 132px;
451	  background: #1e2539;
452	  border: 1px solid #2d364f;
453	  border-left: 4px solid #f87171;
454	  border-radius: 8px;
455	  padding: 18px;
456	}
457	
458	.dashboard-alert-card {
459	  display: flex;
460	  flex-direction: column;
461	  gap: 8px;
462	  color: inherit;
463	  text-decoration: none;
464	}
465	
466	.dashboard-alert-card span {
467	  width: fit-content;
468	  border-radius: 6px;
469	  background: rgba(248, 113, 113, 0.12);
470	  color: #f87171;
471	  padding: 4px 8px;
472	  font-size: 0.68rem;
473	  font-weight: 850;
474	  text-transform: uppercase;
475	}
476	
477	.dashboard-alert-card h2,
478	.dashboard-alert-empty h2 {
479	  margin: 0;
480	  color: #f8fafc;
481	  font-size: 1rem;
482	}
483	
484	.dashboard-alert-card p,
485	.dashboard-alert-card small,
486	.dashboard-alert-empty p,
487	.dashboard-alert-offline {
488	  margin: 0;
489	  color: #94a3b8;
490	  font-size: 0.8rem;
491	}
492	
493	.dashboard-alert-card small {
494	  margin-top: auto;
495	  color: #60a5fa;
496	}
497	
498	.dashboard-alert-empty {
499	  grid-column: 1 / -1;
500	  border-left-color: #34d399;
501	}
502	
503	.dashboard-alert-empty p {
504	  margin-top: 8px;
505	}
506	
507	.dashboard-alert-offline {
508	  margin-bottom: 12px;
509	  color: #f87171;
510	}
511	
512	/* --- CHARTS (2-Column Bottom) --- */
513	.charts-section {
514	  display: grid;
515	  grid-template-columns: 1fr 1fr;
516	  gap: 20px;
517	}
518	
519	.chart-card {
520	  background: #1e2539;
521	  padding: 20px;
522	  border-radius: 12px;
523	  border: 1px solid #2d364f;
524	}
525	
526	.chart-card h3 {
527	  font-size: 1rem;
528	  color: #e2e8f0;
529	  margin-top: 0;
530	  margin-bottom: 15px;
531	}
532	
533	.mock-bar-chart {
534	  display: flex;
535	  justify-content: space-around;
536	  align-items: flex-end;
537	  height: 200px;
538	  margin-top: 20px;
539	  border-bottom: 1px solid #2d364f;
540	  padding-bottom: 25px;
541	}
542	
543	.bar-wrapper {
544	  width: 30px;
545	  height: 100%;
546	  display: flex;
547	  flex-direction: column;
548	  justify-content: flex-end;
549	  position: relative;
550	}
551	
552	.bar {
553	  width: 100%;
554	  background: linear-gradient(to top, #3b82f6, #93c5fd);
555	  border-radius: 4px 4px 0 0;
556	}
557	
558	.bar-wrapper span {
559	  position: absolute;
560	  bottom: -25px;
561	  width: 100%;
562	  text-align: center;
563	  font-size: 0.7rem;
564	  color: #707a91;
565	}
566	
567	.mock-line-chart {
568	  height: 200px;
569	  background: #0b0f1a;
570	  border: 1px dashed #2d364f;
571	  border-radius: 8px;
572	  display: flex;
573	  align-items: center;
574	  justify-content: center;
575	  margin-top: 20px;
576	  color: #4b5563;
577	  font-size: 0.8rem;
578	}
579	
580	/* =========================================
581	   4. CAMERAS PAGE SPECIFICS
582	   ========================================= */
583	.camera-grid {
584	  display: grid;
585	  grid-template-columns: repeat(auto-fit, minmax(320px, 420px));
586	  gap: 25px;
587	}
588	
589	.camera-card {
590	  background: #1e2539;
591	  border-radius: 12px;
592	  border: 1px solid #2d364f;
593	  overflow: hidden;
594	  transition: transform 0.2s, border-color 0.2s;
595	}
596	
597	.camera-card:hover {
598	  transform: translateY(-3px);
599	  border-color: #3b82f6;
600	}
601	
602	.camera-alert {
603	  border: 1px solid #ef4444;
604	  box-shadow: 0 0 15px rgba(239, 68, 68, 0.2);
605	}
606	
607	/* Video / camera screen area */
608	.camera-feed-placeholder {
609	  width: 100%;
610	  aspect-ratio: 4 / 3;
611	  background: #0b0f1a;
612	  border-bottom: 1px solid #2d364f;
613	  position: relative;
614	  overflow: hidden;
615	}
616	
617	.camera-video {
618	  position: absolute;
619	  inset: 0;
620	  width: 100%;
621	  height: 100%;
622	  object-fit: contain;
623	  object-position: center;
624	  display: block;
625	  background: #000;
626	  z-index: 1;
627	}
628	
629	.camera-overlay {
630	  position: absolute;
631	  inset: 0;
632	  width: 100%;
633	  height: 100%;
634	  pointer-events: none;
635	  z-index: 2;
636	}
637	
638	.feed-live-icon {
639	  position: absolute;
640	  top: 15px;
641	  right: 15px;
642	  color: #ef4444;
643	  font-size: 0.8rem;
644	  font-weight: bold;
645	  animation: blink 2s infinite;
646	  z-index: 5;
647	}
648	
649	@keyframes blink {
650	  0% { opacity: 1; }
651	  50% { opacity: 0.35; }
652	  100% { opacity: 1; }
653	}
654	
655	/* Offline camera text */
656	.feed-offline-text {
657	  color: #4b5563;
658	  font-weight: bold;
659	  letter-spacing: 3px;
660	  font-size: 1rem;
661	}
662	
663	/* Bottom info section */
664	.camera-info {
665	  padding: 20px 24px;
666	  background: #1e2539;
667	  min-height: 85px;
668	}
669	
670	.cam-title-row {
671	  display: flex;
672	  justify-content: space-between;
673	  align-items: center;
674	  margin-bottom: 6px;
675	}
676	
677	.cam-title-row h3 {
678	  margin: 0;
679	  font-size: 1.1rem;
680	  color: #f8fafc;
681	}
682	
683	.camera-info p {
684	  margin: 0;
685	  font-size: 0.9rem;
686	  color: #8ea0c8;
687	}
688	
689	/* Status dots */
690	.status-dot {
691	  width: 10px;
692	  height: 10px;
693	  border-radius: 50%;
694	  display: inline-block;
695	}
696	
697	.dot-online {
698	  background: #34d399;
699	  box-shadow: 0 0 10px #34d399;
700	}
701	
702	.dot-warning {
703	  background: #f59e0b;
704	  box-shadow: 0 0 10px #f59e0b;
705	}
706	
707	.dot-offline {
708	  background: #64748b;
709	  box-shadow: 0 0 10px #64748b;
710	}
711	
712	/* =========================================
713	   5. V-PATROL PAGE SPECIFICS
714	   ========================================= */
715	.vpatrol-container {
716	  background: #1e2539;
717	  border-radius: 12px;
718	  border: 1px solid #2d364f;
719	  padding: 10px;
720	}
721	
722	.incident-row {
723	  display: flex;
724	  align-items: center;
725	  padding: 20px;
726	  border-bottom: 1px solid #2d364f;
727	  gap: 30px;
728	}
729	
730	.incident-row:last-child {
731	  border-bottom: none;
732	}
733	
734	.severity-critical { border-left: 4px solid #ef4444; }
735	.severity-high { border-left: 4px solid #f59e0b; }
736	.severity-medium { border-left: 4px solid #3b82f6; }
737	.severity-safe { border-left: 4px solid #34d399; }
738	
739	.incident-time {
740	  display: flex;
741	  flex-direction: column;
742	  min-width: 100px;
743	}
744	
745	.incident-time strong { color: #f8fafc; font-size: 0.95rem; }
746	.incident-time span { color: #707a91; font-size: 0.75rem; margin-top: 4px; }
747	
748	.incident-details {
749	  flex: 1;
750	}
751	
752	.incident-details h3 { margin: 0 0 5px 0; font-size: 1.05rem; color: #f8fafc; }
753	.incident-details p { margin: 0; font-size: 0.9rem; color: #94a3b8; }
754	
755	.review-btn {
756	  background: transparent;
757	  border: 1px solid #3b82f6;
758	  color: #60a5fa;
759	  padding: 8px 16px;
760	  border-radius: 6px;
761	  cursor: pointer;
762	  font-weight: 600;
763	  transition: background 0.2s, color 0.2s;
764	}
765	
766	.review-btn:hover {
767	  background: #3b82f6;
768	  color: white;
769	}
770	
771	/* =========================================
772	   6. RESPONSIVE DESIGN (TABLET & MOBILE)
773	   ========================================= */
774	.mobile-menu-btn {
775	  display: none !important; 
776	  position: absolute;
777	}
778	
779	@media (max-width: 1024px) {
780	  .top-summary-row, .dashboard-summary-grid { grid-template-columns: repeat(2, 1fr); }
781	  .activity-cards-grid,
782	  .dashboard-alert-grid { grid-template-columns: repeat(2, 1fr); }
783	  .charts-section { grid-template-columns: 1fr; }
784	}
785	
786	@media (max-width: 768px) {
787	  /* Hamburger Button */
788	  .mobile-menu-btn {
789	    display: flex !important;
790	    position: fixed;
791	    top: 15px;
792	    left: 15px;
793	    z-index: 1000;
794	    width: 45px;
795	    height: 45px;
796	    background: rgba(30, 41, 59, 0.8);
797	    color: white;
798	    border: 1px solid #334155;
799	    border-radius: 8px;
800	    align-items: center;
801	    justify-content: center;
802	    font-size: 1.5rem;
803	    cursor: pointer;
804	    backdrop-filter: blur(5px);
805	  }
806	
807	  /* Sidebar Canvas Behavior */
808	  .sidebar {
809	    position: fixed;
810	    left: -100%;
811	    z-index: 999;
812	  }
813	
814	  .sidebar.open {
815	    left: 0;
816	  }
817	
818	  /* Activate Close Button inside Sidebar */
819	  .close-sidebar-btn {
820	    display: flex; 
821	    background: transparent;
822	    color: #94a3b8;
823	    border: none;
824	    font-size: 1.5rem;
825	    cursor: pointer;
826	    padding: 5px;
827	    align-items: center;
828	    justify-content: center;
829	    transition: color 0.3s ease;
830	  }
831	
832	  .close-sidebar-btn:hover,
833	  .close-sidebar-btn:active {
834	    color: #f8fafc;
835	  }
836	
837	  /* Overlay Background */
838	  .sidebar-overlay {
839	    position: fixed;
840	    top: 0;
841	    left: 0;
842	    width: 100vw;
843	    height: 100vh;
844	    background: rgba(0, 0, 0, 0.6);
845	    backdrop-filter: blur(2px);
846	    z-index: 998; 
847	  }
848	
849	  /* Main Content Adjustments */
850	  .dashboard-main {
851	    padding: 90px 20px 20px;
852	  }
853	
854	  .dashboard-header {
855	    flex-direction: column;
856	    align-items: flex-start;
857	    gap: 15px;
858	  }
859	
860	  .header-time {
861	    text-align: left;
862	  }
863	
864	  .top-summary-row, 
865	  .activity-cards-grid,
866	  .dashboard-alert-grid {
867	    grid-template-columns: 1fr;
868	  }
869	
870	  .dashboard-section-heading {
871	    flex-direction: column;
872	  }
873	}
