file.content:
/* GLOBAL STYLING */
*, *::before, *::after {
  box-sizing: border-box;
}

:root {
  font-family: Inter, system-ui, Avenir, Helvetica, Arial, sans-serif;
  background-color: #0f172a;
  color: #f8fafc;
}

body {
  margin: 0;
  padding: 0;
  min-height: 100vh;
  width: 100%;
  overflow-x: hidden; 
  position: relative; 
}

#root {
  width: 100%;
  overflow-x: hidden; 
}

::-webkit-scrollbar {
  width: 8px;
}

::-webkit-scrollbar-track {
  background: #0f172a; 
}

::-webkit-scrollbar-thumb {
  background: #1e293b; 
  border-radius: 10px; 
}

::-webkit-scrollbar-thumb:hover {
  background: #3b82f6; 
}

