/* =========================================
   3b. FM OPERATIONAL ANALYTICS (real DB-backed charts, not the mock-* classes)
   ========================================= */
.dashboard-analytics-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  margin-bottom: 30px;
}

.analytics-panel {
  background: #1e2539;
  border: 1px solid #2d364f;
  border-radius: 12px;
  padding: 20px;
  min-width: 0; /* let the panel shrink inside the grid instead of forcing overflow */
}

.analytics-panel-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 16px;
}

.analytics-panel-head h3 {
  margin: 0;
  font-size: 1rem;
  color: #e2e8f0;
}

.analytics-subtle { color: #707a91; font-size: 0.78rem; }

.analytics-legend {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
}

.legend-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: #94a3b8;
  font-size: 0.78rem;
}

.legend-swatch {
  width: 12px;
  height: 12px;
  border-radius: 3px;
  display: inline-block;
}

.legend-high { background: #f59e0b; }
.legend-critical { background: #ef4444; }

.analytics-empty {
  margin: 8px 0 0;
  color: #94a3b8;
  font-size: 0.85rem;
  line-height: 1.5;
}

/* --- Seven-day trend: grouped vertical bars --- */
.trend-chart {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 8px;
  height: 180px;
  padding-top: 10px;
}

.trend-day {
  flex: 1 1 0;
  min-width: 0;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
}

.trend-count {
  font-size: 0.78rem;
  font-weight: 700;
  color: #e2e8f0;
}

.trend-bar-stack {
  width: 60%;
  max-width: 34px;
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: stretch;
}

.trend-bar {
  width: 100%;
  border-radius: 3px 3px 0 0;
  min-height: 0;
}

/* Critical sits on top of High in the stack; each keeps a hairline when non-zero. */
.trend-bar-critical { background: #ef4444; }
.trend-bar-high { background: #f59e0b; border-radius: 0; }
.trend-day .trend-bar-high:last-child { border-radius: 3px 3px 0 0; }

.trend-label {
  font-size: 0.72rem;
  color: #707a91;
  white-space: nowrap;
}

/* --- Top alert zones: horizontal bars --- */
.zones-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.zone-row {
  display: grid;
  grid-template-columns: minmax(80px, 34%) 1fr auto;
  align-items: center;
  gap: 12px;
}

.zone-name {
  font-size: 0.85rem;
  color: #e2e8f0;
  overflow: hidden;
  text-overflow: ellipsis;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  word-break: break-word;
}

.zone-bar-track {
  background: #0b0f1a;
  border-radius: 999px;
  height: 12px;
  overflow: hidden;
}

.zone-bar {
  display: block;
  height: 100%;
  min-width: 4px;
  border-radius: 999px;
  background: linear-gradient(to right, #3b82f6, #60a5fa);
}

.zone-count {
  font-size: 0.9rem;
  font-weight: 700;
  color: #f8fafc;
  min-width: 1.5ch;
  text-align: right;
}

/* Screen-reader-only helper (mirrors chart data as a table for assistive tech). */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

