/* ---- Table: horizontal scroll + fixed layout for balanced columns ----
   Scoped to .inc-table / .inc-table-wrap (NOT .dashboard-main .management-table)
   so these rules cannot leak into other pages' tables — all page CSS ends up
   in one global bundle. */
.inc-table-wrap {
  overflow-x: auto;
  overflow-y: hidden;
}

.management-table.inc-table {
  min-width: 880px;
  table-layout: fixed;
}

/* Tighter side padding than the default 1.5rem so every header fits its
   column at the 880px minimum (CONFIDENCE is the widest at ~89px). */
.inc-table th,
.inc-table td {
  padding-left: 14px;
  padding-right: 14px;
}

/* Column widths — total 100%
   Order: TIMESTAMP | LOCATION | PERSON | SOURCE | CONFIDENCE | SEVERITY | STATUS | ACTIONS */
.inc-table th:nth-child(1) { width: 12.7%; }
.inc-table th:nth-child(2) { width: 12.5%; }
.inc-table th:nth-child(3) { width: 10.5%; }
.inc-table th:nth-child(4) { width: 10%; }
.inc-table th:nth-child(5) { width: 13.5%; }
.inc-table th:nth-child(6) { width: 11%; }
.inc-table th:nth-child(7) { width: 11.8%; }
.inc-table th:nth-child(8) { width: 18%; }

/* Timestamp: date on line 1, time on line 2 */
.inc-table td:nth-child(1) {
  white-space: nowrap;
  line-height: 1.5;
}

/* ---- Sticky Actions column ----
   Sticky cells need opaque backgrounds; each value below matches the
   composited colour of the row state it sits on, so the column blends
   in instead of reading as a separate block. */
.inc-table th:last-child {
  position: sticky;
  right: 0;
  z-index: 2;
  background: #172032; /* rgba(30,41,59,.5) header tint over #0f172a */
}

.inc-table .actions-cell {
  position: sticky;
  right: 0;
  z-index: 1;
  background: #0f172a;
  text-align: center;
}

/* Compact buttons so the group fits the sticky column on laptop widths */
.inc-table th:last-child,
.inc-table .actions-cell {
  padding-left: 10px;
  padding-right: 10px;
}

.inc-table .actions-cell .action-btn {
  min-width: 64px;
}

