(() => {
  const de = document.documentElement;
  const vw = de.clientWidth;
  const offenders = [];
  document.querySelectorAll('*').forEach(el => {
    const r = el.getBoundingClientRect();
    // element extends past the right viewport edge by > 2px
    if (r.right > vw + 2 && r.width > 0 && r.width <= 2000) {
      offenders.push({
        cls: (el.className && el.className.toString ? el.className.toString().slice(0,60) : ''),
        tag: el.tagName.toLowerCase(),
        right: Math.round(r.right), width: Math.round(r.width), left: Math.round(r.left)
      });
    }
  });
  // dedupe by class+tag, keep widest
  const seen = {};
  offenders.forEach(o => { const k=o.tag+'.'+o.cls; if(!seen[k]||o.width>seen[k].width) seen[k]=o; });
  return JSON.stringify({
    path: location.pathname, viewport: vw,
    docScrollW: de.scrollWidth, docClientW: de.clientWidth,
    bodyOverflow: de.scrollWidth > de.clientWidth,
    offenders: Object.values(seen).slice(0,15)
  }, null, 1);
})();

