      }
    });
    return { vw, docScrollW: de.scrollWidth, docClientW: de.clientWidth, bodyOverflow: de.scrollWidth > de.clientWidth+1, worstInnerScroll: worst };
  };
  // Can't resize from JS reliably in this pane; just measure current width repeatedly won't help.
  return JSON.stringify(measure(), null, 1);
})();

