file.content:
.inc-table .actions-cell .action-btn {
  min-width: 64px;
}

/* ---- Mobile: keep the dense 8-column incident table as a horizontally-scrollable
   table instead of the global .management-table card conversion (Management.css).
   That conversion hides <thead> and blocks the cells, but this table has no
   data-labels and keeps its 880px min-width + sticky actions, so it would render as
   an unlabeled, half-broken hybrid. Overriding it back to a real table (inside the
   existing .inc-table-wrap overflow-x:auto wrapper) preserves every field and action.
   Compound selectors (.management-table.inc-table …) outrank the generic card rules. */
@media (max-width: 768px) {
  .management-table.inc-table { display: table; }
  .management-table.inc-table thead { display: table-header-group; }
  .management-table.inc-table tbody { display: table-row-group; }
  .management-table.inc-table tr {
    display: table-row;
    margin: 0;
    background: transparent;
    border: 0;
    border-radius: 0;
    padding: 0;
    box-shadow: none;
  }
  .management-table.inc-table td {
    display: table-cell;
    width: auto;
    justify-content: initial;
    align-items: initial;
  }
  .management-table.inc-table td::before { content: none; }
}

.inc-table .actions-cell .action-button-group {
  grid-template-columns: repeat(2, minmax(64px, 1fr));
  max-width: none;
  width: fit-content;
  margin: 0 auto;
}

