input.new_string:
/* ---- Mobile (<=768px): the dense 8-column incident table becomes labelled cards.
   Horizontal-scrolling an 880px table to reach the far-right Actions column is awkward
   one-handed for a guard on a phone, so on mobile we let the global .management-table
   card conversion (Management.css) take over. Here we only undo the .inc-table-specific
   desktop rules that would fight it: the 880px min-width, fixed layout, and the sticky
   Actions column. Every field keeps its data-label (added in IncidentDashboard.jsx),
   so no timestamp/location/person/source/confidence/severity/status/action is lost.
   The desktop table (>=769px) is untouched. */
@media (max-width: 768px) {
  .inc-table-wrap {
    overflow-x: visible; /* cards flow vertically; no horizontal scroll needed */
  }

  .management-table.inc-table {
    min-width: 0;
    table-layout: auto;
  }

  /* Cancel the desktop sticky Actions column — meaningless once cells are stacked. */
  .inc-table th:last-child,
  .inc-table .actions-cell {
    position: static;
    right: auto;
    z-index: auto;
    background: transparent;
  }

  /* The timestamp cell keeps its two lines but must not force a wide nowrap row. */
  .inc-table td:nth-child(1) {
    white-space: normal;
  }
}

