(() => {
  const de = document.documentElement, vw = de.clientWidth;
  const wrap=document.querySelector('.inc-table-wrap');
  const tbl=document.querySelector('.inc-table');
  const theadDisplay = tbl ? getComputedStyle(tbl.querySelector('thead')).display : null;
  const firstRow = document.querySelector('.inc-table tbody tr');
  const labels = firstRow ? [...firstRow.querySelectorAll('td[data-label]')].map(td=>td.getAttribute('data-label')) : [];
  // does first row show all fields as blocks (card)?
  const tdDisplay = firstRow ? getComputedStyle(firstRow.querySelector('td')).display : null;
  const actionBtns = firstRow ? [...firstRow.querySelectorAll('button')].map(b=>b.textContent.trim()) : [];
  let bodyOverflow=de.scrollWidth>de.clientWidth+1;
  return JSON.stringify({path:location.pathname,vw,bodyOverflow,
    theadDisplay, tdDisplay, wrapScrollW: wrap?wrap.scrollWidth:null, wrapClientW: wrap?wrap.clientWidth:null,
    rowDataLabels: labels, actionBtns});
})();

