(async () => {
  const t = localStorage.getItem('accessToken');
  try {
    const r = await fetch('/api/dashboard/summary', { headers: { Authorization: 'Bearer '+t }, cache:'no-store' });
    const txt = await r.text();
    let j={}; try{j=JSON.parse(txt);}catch(e){return 'non-json: '+txt.slice(0,120);}
    return JSON.stringify({ status: r.status, hasAnalytics: !!j.analytics, trend: (j.analytics?.alertTrend7Days||[]).map(d=>`${d.label}:${d.high}/${d.critical}`), zones: (j.analytics?.topAlertZones7Days||[]).map(z=>`${z.zone}=${z.count}`) });
  } catch(e){ return 'err: '+e.message; }
})();

