(() => {
  const de = document.documentElement, vw = de.clientWidth;
  let offenders = [];
  document.querySelectorAll('*').forEach(el => {
    const c = el.className.toString();
    if (c.includes('grecaptcha') || el.tagName==='IFRAME' || el.closest('.sr-only')) return;
    if (getComputedStyle(el).position==='fixed') return;
    const r = el.getBoundingClientRect();
    if (r.right > vw + 2 && r.width > 0 && r.width <= 3000) offenders.push({cls:c.slice(0,40),tag:el.tagName.toLowerCase(),w:Math.round(r.width)});
  });
  const seen={}; offenders.forEach(o=>{const k=o.tag+o.cls; if(!seen[k]||o.w>seen[k].w)seen[k]=o;});
  const heading=[...document.querySelectorAll('h1,h2')].find(h=>!h.closest('.sidebar')&&h.getBoundingClientRect().width>0);
  return JSON.stringify({path:location.pathname,vw,bodyOverflow:de.scrollWidth>de.clientWidth+1,heading:heading?heading.textContent.trim().slice(0,22):null,offenders:Object.values(seen).slice(0,5)});
})();

