(async () => {
  const measure = () => {
    const de = document.documentElement, vw = de.clientWidth;
    let offenders = [];
    document.querySelectorAll('*').forEach(el => {
      const c = el.className.toString();
      if (c.includes('grecaptcha') || el.tagName==='IFRAME' || el.closest('.sr-only')) return;
      if (getComputedStyle(el).position==='fixed') return;
      const r = el.getBoundingClientRect();
      if (r.right > vw + 2 && r.width > 0 && r.width <= 3000) offenders.push({cls:c.slice(0,35),tag:el.tagName.toLowerCase(),w:Math.round(r.width)});
    });
    const seen={}; offenders.forEach(o=>{const k=o.tag+o.cls; if(!seen[k]||o.w>seen[k].w)seen[k]=o;});
    return {path:location.pathname, vw, bodyOverflow:de.scrollWidth>de.clientWidth+1, offenders:Object.values(seen).slice(0,4)};
  };
  const nav = (href) => new Promise(res => { const l=document.querySelector(`.sidebar-nav a[href="${href}"]`); if(l)l.click(); setTimeout(res, 500); });
  const out = [];
  for (const href of ['/object-detection','/incidents','/dashboard','/cameras','/detection-settings']) {
    await nav(href); out.push(measure());
  }
  return JSON.stringify(out);
})();

