(async () => {
  // remount dashboard to refetch
  const cam=document.querySelector('.sidebar-nav a[href="/cameras"]'); if(cam)cam.click();
  await new Promise(r=>setTimeout(r,400));
  const dash=document.querySelector('.sidebar-nav a[href="/dashboard"]'); if(dash)dash.click();
  await new Promise(r=>setTimeout(r,700));
  const empties=[...document.querySelectorAll('.analytics-empty')].map(e=>e.textContent.trim().slice(0,50));
  const hasBars=!!document.querySelector('.trend-chart') || !!document.querySelector('.zone-row');
  return JSON.stringify({emptyStateMessages: empties, stillHasBars: hasBars, headings:[...document.querySelectorAll('.analytics-panel h3')].map(h=>h.textContent)});
})();

(() => {
  const vw = document.documentElement.clientWidth, vh = document.documentElement.clientHeight;
  const fixed = [];
  document.querySelectorAll('body *').forEach(el => {
    const cs = getComputedStyle(el);
    if (cs.position === 'fixed' && el.offsetWidth>0 && el.offsetHeight>0) {
      const r = el.getBoundingClientRect();
      const cls = (el.className||'').toString().slice(0,30);
      if (r.width < vw) fixed.push({cls: cls||el.tagName.toLowerCase(), w:Math.round(r.width), h:Math.round(r.height), left:Math.round(r.left), top:Math.round(r.top), bottom:Math.round(r.bottom), right:Math.round(r.right)});
    }
  });
  const seen={}; fixed.forEach(f=>{seen[f.cls]=f;});
  return JSON.stringify({vw, vh, fixedWidgets: Object.values(seen).slice(0,8)});
})();
